let phone = '';
try {
  phone = $('Edit Fields').first().json.phone.replace(/=/g, '');
} catch(e) {
  try {
    phone = $('Extract Transcription').first().json.phone.replace(/=/g, '');
  } catch(e2) {
    phone = '';
  }
}
const isNonCustomer = $input.first().json.isNonCustomer === true;

// Find the actual text block regardless of position — models using extended
// thinking (like Sonnet, now used for high-value moments via smart routing)
// can return a "thinking" block BEFORE the text block, so content[0] is not
// reliably the reply anymore. Search for the first block with type "text".
const contentBlocks = ($('Claude API').first().json.content) || [];
const textBlock = contentBlocks.find(b => b && b.type === 'text');
let reply = (textBlock && textBlock.text) || '';

const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';

const ADMIN_ALERT_CHAT_ID = '6150148292'; // fixed admin notification channel — NOT a data fallback
const botTokenForAlert = '[REDACTED_TELEGRAM_BOT_TOKEN]';

// ═══ RESOLVE WHICH SELLER OWNS THIS CONVERSATION (for usage logging below) ═══
let sellerChatId = null;
try {
  const incomingPhoneNumberId = $('webhook').first().json.body.entry[0].changes[0].value.metadata.phone_number_id;
  if (incomingPhoneNumberId) {
    const sellerLookup = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?phone_number_id=eq.' + incomingPhoneNumberId + '&select=chat_id&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    if (sellerLookup && sellerLookup.length > 0) sellerChatId = sellerLookup[0].chat_id;
  }
} catch(e) {}

if (!sellerChatId) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botTokenForAlert + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: ADMIN_ALERT_CHAT_ID,
        text: '⚠️ ADMIN ALERT (Extract Reply): Could not identify which seller a WhatsApp message belongs to. AI usage will not be logged for this message.\n\nCustomer phone: ' + phone
      })
    });
  } catch (e2) {}
}

// ═══ LOG AI USAGE (tokens + reply text + which model actually responded) ═══
try {
  const usageData = $('Claude API').first().json.usage || {};
  const modelUsed = $('Claude API').first().json.model || 'unknown';
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/ai_usage_log',
    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      seller_id: sellerChatId,
      input_tokens: usageData.input_tokens || 0,
      output_tokens: usageData.output_tokens || 0,
      reply_text: reply,
      node_name: 'main_whatsapp_chat (' + modelUsed + ')'
    })
  });
} catch(e) {}

// If non-customer detected — don't send anything to WhatsApp
if (isNonCustomer || reply.includes('[NOT_CUSTOMER]')) {
  return [{ json: { phone, reply: '', waBody: '{"messaging_product":"whatsapp","to":"000","type":"text","text":{"body":"."}}', isOrderConfirmed: 'false', askSellerQuestion: null, isBumpOffered: 'false', isUpsellOffered: 'false', isNonCustomer: true } }];
}

// Detect language tag
const langMatch = reply.match(/\[DETECTED_LANG:\s*([^\|]+)\|\s*([^\]]+)\]/);
let detectedLang = null;
let detectedDialect = null;
if (langMatch) {
  detectedLang = langMatch[1].trim();
  detectedDialect = langMatch[2].trim();
  reply = reply.replace(/\[DETECTED_LANG:[^\]]+\]/, '').trim();
}

// Detect tags
const isOrderConfirmed = reply.includes('[ORDER_CONFIRMED]') ? 'true' : 'false';
const isBumpOffered = reply.includes('[BUMP_OFFERED]') ? 'true' : 'false';
const isUpsellOffered = reply.includes('[UPSELL_OFFERED]') ? 'true' : 'false';

// Detect ASK_SELLER tag
let askSellerQuestion = null;
const askSellerMatch = reply.match(/\[ASK_SELLER:\s*(.+?)\]/);
if (askSellerMatch) {
  askSellerQuestion = askSellerMatch[1].trim();
} else {
  // Safety net: the model sometimes says (in natural language) that it will
  // "check and get back to you" without actually including the required
  // [ASK_SELLER] tag — the same tag-reliability gap found with onboarding
  // earlier. Without this, the seller never finds out a customer is waiting
  // on an answer at all. Detect that promise-to-check pattern and escalate
  // anyway, using the customer's own message as the question.
  const soundsLikeCheckPromise = /let me check|i'?ll check|will check|check on that|check and get back|check with the team|check with production|check with sales|check with management|need to check|بتأكد|بتحقق|بشوف وبرد|بسأل الفريق|بسأل الإدارة/i.test(reply);
  if (soundsLikeCheckPromise) {
    let customerMessage = '';
    try { customerMessage = $('Build Prompt  (how to say)').first().json.message || ''; } catch (e) {}
    askSellerQuestion = customerMessage
      ? `(auto-detected — no tag found) Customer asked: "${customerMessage}"`
      : '(auto-detected — no tag found) Ahmad told the customer he\'d check on something, but the specific question could not be recovered.';
  }
}

// Clean reply — remove ALL tags before sending to customer, plus a safety net
// stripping markdown asterisks (the model doesn't always reliably follow the
// "no markdown" rule on its own, the same gap found and fixed in Telegram).
const cleanReply = reply
  .replace('[ORDER_CONFIRMED]', '')
  .replace(/\[ASK_SELLER:.*?\]/g, '')
  .replace('[BUMP_OFFERED]', '')
  .replace('[UPSELL_OFFERED]', '')
  .replace(/\*\*/g, '')
  .replace(/\*/g, '')
  .trim();

const waBody = JSON.stringify({
  messaging_product: "whatsapp",
  to: phone,
  type: "text",
  text: { body: cleanReply }
});

// Save detected language to customer record (fire and forget)
if (detectedLang && phone && sellerChatId) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/customers?phone=eq.' + phone + '&seller_id=eq.' + sellerChatId,
      headers: {
        'apikey': anonKey,
        'Authorization': 'Bearer ' + anonKey,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ preferred_language: detectedLang, preferred_dialect: detectedDialect })
    });
  } catch(e) {}
}

return [{ json: { phone, reply: cleanReply, waBody, isOrderConfirmed, askSellerQuestion, isBumpOffered, isUpsellOffered, isNonCustomer: false } }];

let phone, message;
try {
  phone = $('Edit Fields').first().json.phone;
  message = $('Edit Fields').first().json.message;
} catch(e) {
  phone = $('Extract Audio Info').first().json.phone;
  message = $('Extract Transcription').first().json.message;
}
phone = phone.toString().replace(/=/g, '').replace(/\+/g, '');
message = message ? message.toString().replace(/^=+/, '') : '';

const replyContentBlocks = ($('Claude API').first().json.content) || [];
const replyTextBlock = replyContentBlocks.find(b => b && b.type === 'text');
const reply = (replyTextBlock && replyTextBlock.text) || '';
const cleanReply = reply ? reply.toString().replace(/^=+/, '') : '';

let productType = $('Build Prompt  (how to say)').first().json.productType || 'unknown';
productType = productType.toString().replace(/^=+/, '');

const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';

const ADMIN_ALERT_CHAT_ID = '6150148292'; // fixed admin notification channel — NOT a data fallback
const botToken = '[REDACTED_TELEGRAM_BOT_TOKEN]';

// ═══ RESOLVE WHICH SELLER OWNS THIS CONVERSATION (generic, multi-seller ready) ═══
let sellerChatId = null;
try {
  const incomingPhoneNumberId = $('webhook').first().json.body.entry[0].changes[0].value.metadata.phone_number_id;
  if (incomingPhoneNumberId) {
    const sellerLookup = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?phone_number_id=eq.' + incomingPhoneNumberId + '&select=chat_id&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    if (sellerLookup && sellerLookup.length > 0) sellerChatId = sellerLookup[0].chat_id;
  }
} catch(e) {}

if (!sellerChatId) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: ADMIN_ALERT_CHAT_ID,
        text: '⚠️ ADMIN ALERT (Prepare Save Data): Could not identify which seller a WhatsApp conversation belongs to. Nothing was saved, to avoid misattributing it to the wrong seller.\n\nCustomer phone: ' + phone
      })
    });
  } catch (e) {}
  return [{ json: { phone, message, reply: cleanReply, productType, sellerChatId: null, sellerResolutionFailed: true } }];
}

// Save user message
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations',
  headers: {
    'apikey': anonKey,
    'Authorization': 'Bearer ' + anonKey,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: JSON.stringify({
    phone_number: phone,
    role: 'user',
    message: message,
    timestamp: new Date().toISOString(),
    product_type: productType,
    seller_id: sellerChatId
  })
});

// Save assistant reply
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations',
  headers: {
    'apikey': anonKey,
    'Authorization': 'Bearer ' + anonKey,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: JSON.stringify({
    phone_number: phone,
    role: 'assistant',
    message: cleanReply,
    timestamp: new Date().toISOString(),
    product_type: productType,
    seller_id: sellerChatId
  })
});

return [{ json: { phone, message, reply: cleanReply, productType, sellerChatId } }];

let rawPhone;
let rawMessage = '';
try {
  rawPhone = $('Edit Fields').first().json.phone;
  rawMessage = $('Edit Fields').first().json.message || '';
} catch(e) {
  try {
    rawPhone = $('Extract Audio Info').first().json.phone;
  } catch(e2) {
    rawPhone = '';
  }
}
const phone = rawPhone.toString().replace(/=/g, '').replace(/\+/g, '');
const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';
const anthropicKey = '[REDACTED_ANTHROPIC_KEY]';

// ═══ RESOLVE WHICH SELLER OWNS THIS NUMBER (generic, multi-seller ready) ═══
let incomingPhoneNumberId = null;
try {
  incomingPhoneNumberId = $('webhook').first().json.body.entry[0].changes[0].value.metadata.phone_number_id;
} catch(e) {}

const ADMIN_ALERT_CHAT_ID = '6150148292'; // fixed admin notification channel — NOT a data fallback
const botToken = '[REDACTED_TELEGRAM_BOT_TOKEN]';

let metaToken = null;
let phoneNumberId = incomingPhoneNumberId || null;
let sellerChatId = null;
try {
  if (incomingPhoneNumberId) {
    const sellerLookup = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?phone_number_id=eq.' + incomingPhoneNumberId + '&select=chat_id,meta_token,phone_number_id&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    if (sellerLookup && sellerLookup.length > 0) {
      metaToken = sellerLookup[0].meta_token;
      phoneNumberId = sellerLookup[0].phone_number_id;
      sellerChatId = sellerLookup[0].chat_id;
    }
  }
} catch(e) {}

// Full halt if the seller can't be identified — this node's output determines
// which WhatsApp Business account/token actually sends the reply, so guessing
// wrong here would mean sending a message from the WRONG seller's WhatsApp
// number to a customer who never contacted them. Better to leave this message
// temporarily unanswered (recoverable) than send from the wrong account.
if (!sellerChatId || !metaToken) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: ADMIN_ALERT_CHAT_ID,
        text: '🚨 ADMIN ALERT (Check AI Status): Could not identify which seller a WhatsApp message belongs to, or that seller has no meta_token configured. The message was NOT answered, to avoid sending a reply from the wrong WhatsApp Business account.\n\nIncoming phone_number_id: ' + (incomingPhoneNumberId || 'unknown') + '\nCustomer phone: ' + phone
      })
    });
  } catch (e) {}
  return [];
}



// ═══════════════════════════════════════════════
// OPT-IN REPLY CHECK — runs before anything else
// If this phone is awaiting a yes/no opt-in reply (from a deleted seller's
// customer being asked if they want offers from other businesses), handle
// that here and stop the pipeline — don't let the sales AI see this message.
// ═══════════════════════════════════════════════
try {
  const pendingRows = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_optin?phone=eq.' + phone + '&status=eq.pending&select=*',
    headers: { apikey: anonKey, Authorization: 'Bearer ' + anonKey }
  });

  if (pendingRows && pendingRows.length > 0) {
    const msgLower = (rawMessage || '').toLowerCase();
    const isYes = msgLower.includes('نعم') || msgLower.includes('اي') || msgLower.includes('ايه') || msgLower.includes('yes') || msgLower.includes('موافق') || msgLower.includes('ok');
    const isNo = msgLower.includes('لا') || msgLower.includes('no') || msgLower.includes('رفض') || msgLower.includes('ما اريد') || msgLower.includes('ماريد');

    async function sendReply(text) {
      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages',
          headers: { Authorization: 'Bearer ' + metaToken, 'Content-Type': 'application/json' },
          body: JSON.stringify({ messaging_product: 'whatsapp', to: phone, type: 'text', text: { body: text } })
        });
      } catch (e) {}
    }

    if (isYes) {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_optin?phone=eq.' + phone,
        headers: { apikey: anonKey, Authorization: 'Bearer ' + anonKey, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
        body: JSON.stringify({ status: 'accepted' })
      });
      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/shared_leads?on_conflict=phone',
          headers: { apikey: anonKey, Authorization: 'Bearer ' + anonKey, 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates' },
          body: JSON.stringify({ phone, interested_categories: pendingRows[0].product_category || '' })
        });
      } catch (e) {}
      let confirmMsg = 'تمام، شكراً! راح نحاول نعطيك أفضل العروض بالمستقبل.';
      try {
        const langResp = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://api.anthropic.com/v1/messages',
          headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
          body: JSON.stringify({
            model: 'claude-haiku-4-5-20251001',
            max_tokens: 60,
            system: 'Identify the language of this message, then write a short, warm confirmation in that SAME language, telling them: "Great, thank you! We\'ll try to give you the best offers in the future." Output ONLY the confirmation message, nothing else.',
            messages: [{ role: 'user', content: rawMessage }]
          })
        });
        const generated = (langResp && langResp.content && langResp.content[0] && langResp.content[0].text || '').trim();
        if (generated) confirmMsg = generated;
      } catch (e) {}
      await sendReply.call(this, confirmMsg);
    } else if (isNo) {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_optin?phone=eq.' + phone,
        headers: { apikey: anonKey, Authorization: 'Bearer ' + anonKey, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
        body: JSON.stringify({ status: 'declined' })
      });
      await sendReply.call(this, 'تمام، ما راح نستخدم رقمك بعد الآن.\n\nUnderstood, we won\'t contact you further.');
    } else {
      await sendReply.call(this, 'آسف، ما فهمت. تريد تستلم عروض من بزنسات ثانية؟ رد "نعم" أو "لا".\n\nSorry, I didn\'t understand. Would you like offers from other businesses? Reply "yes" or "no".');
    }

    return [];
  }
} catch (e) {}

// ═══════════════════════════════════════════════
// GLOBAL AI ACTIVE CHECK (seller-wide pause/resume — set from the web
// app's Business settings or Telegram's /pauseall). When paused, also
// send the seller's custom "pause message" if they've set one — this
// mirrors pause-message handling that already existed in "Build Prompt"
// / "send whatsapp", but was unreachable dead code because this node
// (which runs earlier) always halted the pipeline before reaching it.
// ═══════════════════════════════════════════════
try {
  const globalSettings = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/bot_settings?chat_id=eq.' + sellerChatId + '&key=in.(global_ai_active,global_pause_message)&select=key,value',
    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
  });
  const globalMap = {};
  (globalSettings || []).forEach(s => { globalMap[s.key] = s.value; });
  if (globalMap.global_ai_active === 'false') {
    const pauseMsg = globalMap.global_pause_message || '';
    if (pauseMsg) {
      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages',
          headers: { Authorization: 'Bearer ' + metaToken, 'Content-Type': 'application/json' },
          body: JSON.stringify({ messaging_product: 'whatsapp', to: phone, type: 'text', text: { body: pauseMsg } })
        });
      } catch (e) {}
    }
    return [];
  }
} catch (e) {}

// ═══════════════════════════════════════════════
// EXISTING AI ACTIVE CHECK
// ═══════════════════════════════════════════════
const url = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/client_status?phone_number=eq.' + phone + '&seller_id=eq.' + sellerChatId + '&select=ai_active';

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: url,
  headers: {
    'apikey': anonKey,
    'Authorization': 'Bearer ' + anonKey
  }
});

const data = response || [];
let isActive = true;
if (Array.isArray(data) && data.length > 0 && typeof data[0].ai_active !== 'undefined') {
  isActive = data[0].ai_active !== false;
}

if (!isActive) {
  return [];
}

return [{ json: { phone, isActive } }];

// Get message from text or audio path
let message, phone;
try {
  message = $('Edit Fields').first().json.message;
  phone = $('Edit Fields').first().json.phone;
} catch(e) {
  message = $('Extract Transcription').first().json.message;
  phone = $('Extract Audio Info').first().json.phone;
}
message = message ? message.toString().replace(/^=+/, '') : '';
phone = phone ? phone.toString().replace(/=/g, '') : '';
const msgLower = message.toLowerCase();

const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';

// Get history from Get History node
let history = [];
try {
  const items = $input.all();
  for (const item of items) {
    if (item.json && item.json.role && item.json.message) {
      history.push({
        role: item.json.role,
        content: item.json.message.replace(/^=+/, '')
      });
    }
  }
} catch(e) { history = []; }

// Scan ALL text including history
const allText = (message + ' ' + history.map(h => h.content).join(' ')).toLowerCase();

const botToken = '[REDACTED_TELEGRAM_BOT_TOKEN]';
const ADMIN_ALERT_CHAT_ID = '6150148292'; // fixed admin notification channel — NOT a data fallback

// ═══ RESOLVE WHICH SELLER OWNS THIS CONVERSATION (generic, multi-seller ready) ═══
let sellerChatId = null;
try {
  const incomingPhoneNumberId = $('webhook').first().json.body.entry[0].changes[0].value.metadata.phone_number_id;
  if (incomingPhoneNumberId) {
    const sellerLookup = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?phone_number_id=eq.' + incomingPhoneNumberId + '&select=chat_id,business_category,selling_type_audience&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    if (sellerLookup && sellerLookup.length > 0) sellerChatId = sellerLookup[0].chat_id;
  }
} catch(e) {}

if (!sellerChatId) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: ADMIN_ALERT_CHAT_ID,
        text: '⚠️ ADMIN ALERT (Layer 1 - Product Detector): Could not identify which seller a WhatsApp message belongs to — downstream product/knowledge lookups will safely return empty rather than another seller\'s data, but the customer will not get a useful reply this turn.\n\nCustomer phone: ' + phone
      })
    });
  } catch (e) {}
}

// ═══ LOAD THIS SELLER'S ACTUAL PRODUCTS (generic — no hardcoded brands) ═══
let sellerProducts = [];
let sellerProfile = {};
try {
  sellerProducts = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_products?chat_id=eq.' + sellerChatId + '&is_active=eq.true&select=product_name,product_category&limit=20',
    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
  }) || [];
} catch(e) { sellerProducts = []; }
try {
  const profileResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?chat_id=eq.' + sellerChatId + '&select=business_category,selling_type_audience&limit=1',
    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
  });
  if (profileResp && profileResp.length > 0) sellerProfile = profileResp[0];
} catch(e) { sellerProfile = {}; }

// ═══ CHECK CUSTOMER SUMMARY FOR PRODUCT (generic match against real products) ═══
function findMentionedProduct(text) {
  const lower = (text || '').toLowerCase();
  return sellerProducts.find(p => p.product_name && lower.includes(p.product_name.toLowerCase()));
}

let summaryProduct = null;
for (const msg of history) {
  if (msg.content && msg.content.includes('ملخص العميل من البائع:')) {
    summaryProduct = findMentionedProduct(msg.content);
    break;
  }
}

// Detect product — current message + history takes priority, then summary, then seller's only product if they have just one
let product_type = 'unknown';
let product_name = '';
let product_category = '';
let sales_style = '';
let urgency_type = 'normal';

const mentionedProduct = findMentionedProduct(allText);

if (mentionedProduct) {
  product_type = mentionedProduct.product_name;
  product_name = mentionedProduct.product_name;
  product_category = mentionedProduct.product_category || sellerProfile.business_category || 'general';
  sales_style = 'discovery';
} else if (summaryProduct) {
  product_type = summaryProduct.product_name;
  product_name = summaryProduct.product_name;
  product_category = summaryProduct.product_category || sellerProfile.business_category || 'general';
