const conversationMessages = [...history, { role: 'user', content: message }];

// ═══════════════════════════════
// MODEL: Haiku for every message — simple, predictable, low-cost.
// ═══════════════════════════════
const selectedModel = 'claude-haiku-4-5-20251001';

const body = JSON.stringify({
  model: selectedModel,
  max_tokens: 1200,
  system: systemPrompt,
  messages: conversationMessages
});

return [{ json: { body, phone, message, productType: detectedProductType, isNonCustomer: false, globallyPaused: false } }];

const isOrderConfirmed = $('Extract Reply').first().json.isOrderConfirmed;
const askSellerQuestion = $('Extract Reply').first().json.askSellerQuestion;
const reply = $('Extract Reply').first().json.reply;
const phone = $('Extract Reply').first().json.phone;
const waBody = $('Extract Reply').first().json.waBody;
const isNonCustomer = $('Extract Reply').first().json.isNonCustomer;
const botToken = '[REDACTED_TELEGRAM_BOT_TOKEN]';
const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';

const ADMIN_ALERT_CHAT_ID = '6150148292'; // fixed admin notification channel — NOT a data fallback

// ═══ RESOLVE WHICH SELLER OWNS THIS CONVERSATION (generic, multi-seller ready) ═══
let chatId = null;
let salesConfig = {};
try {
  const incomingPhoneNumberId = $('webhook').first().json.body.entry[0].changes[0].value.metadata.phone_number_id;
  if (incomingPhoneNumberId) {
    const sellerLookup = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?phone_number_id=eq.' + incomingPhoneNumberId + '&select=chat_id&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    if (sellerLookup && sellerLookup.length > 0) chatId = sellerLookup[0].chat_id;
  }
} catch(e) {}

if (!chatId) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: ADMIN_ALERT_CHAT_ID,
        text: '⚠️ ADMIN ALERT (Check Order Confirmed): Could not identify which seller a WhatsApp message belongs to — the phone_number_id lookup failed or returned no match. Nothing was saved or sent for this message, to avoid misattributing it to the wrong seller.\n\nCustomer phone: ' + phone
      })
    });
  } catch (e) {}
  return [{ json: { reply: '', phone, waBody: null, isOrderConfirmed: 'false', askSellerQuestion: null, debugResult: { sellerResolutionFailed: true } } }];
}

try {
  const configResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_sales_config?chat_id=eq.' + chatId + '&select=*&limit=1',
    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
  });
  if (configResp && configResp.length > 0) salesConfig = configResp[0];
} catch(e) {}

const currencyLabel = salesConfig.currency_label || 'USD';
const minimumOrderQty = salesConfig.minimum_order_qty || 10; // generic fallback if seller hasn't set one

let debugResult = { isOrderConfirmed, askSellerQuestion, phone, isNonCustomer };

// ═══ HANDLE NON-CUSTOMER (FRIEND/FAMILY) ═══
if (isNonCustomer === true) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/client_status?on_conflict=phone_number,seller_id',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates' },
      body: JSON.stringify({ phone_number: phone, ai_active: false, seller_id: chatId })
    });
    const originalMessage = $('Edit Fields').first().json.message || '';
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: chatId,
        text: '👤 Not a customer!\n\nThis number looks like a friend or family member, not a customer.\nNumber: ' + phone + '\nTheir message: ' + originalMessage + '\n\n⏸ AI has been automatically paused for this number.\nTo turn it back on, type:\n/resume ' + phone
      })
    });
  } catch(e) {
    debugResult.nonCustomerError = e.message;
  }
  return [{ json: { reply: '', phone, waBody: null, isOrderConfirmed: 'false', askSellerQuestion: null, debugResult } }];
}

// ═══ HANDLE ORDER CONFIRMED ═══
if (isOrderConfirmed === 'true' || isOrderConfirmed === true) {
  try {
    const text = '🛒 New order!\n\n' + reply + '\n\nCustomer number: ' + phone;
    const tgResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text: text })
    });
    const messageId = tgResponse.result ? tgResponse.result.message_id.toString() : null;
    debugResult.orderMessageId = messageId;

    if (messageId) {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_orders',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
        body: JSON.stringify({ phone_number: phone, telegram_message_id: messageId, status: 'pending', seller_id: chatId })
      });
      debugResult.orderSaved = true;
    }

    // ═══ EXTRACT ORDER DETAILS FROM REPLY (AI-based, works in any language) ═══
    let productName = 'unknown';
    let deliveryAddress = '';
    let city = '';
    let quantity = 1;
    let orderTotal = 0;
    let extractedItems = [];

    try {
      // Fetch recent conversation history — the single confirming message
      // (e.g. "great, confirmed!") often doesn't repeat product/quantity/
      // address details already established earlier in the conversation.
      // Extracting from just that one isolated message misses everything,
      // producing exactly the "unknown"/0/empty result found in testing.
      let recentConvoText = reply;
      try {
        const recentConvo = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations?phone_number=eq.' + phone + '&seller_id=eq.' + chatId + '&select=role,message&order=timestamp.desc&limit=16',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
        });
        if (recentConvo && recentConvo.length > 0) {
          recentConvoText = recentConvo.reverse().map(m => (m.role === 'user' ? 'Customer: ' : 'Seller: ') + m.message).join('\n');
        }
      } catch (eHist) {}

      const extractResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.anthropic.com/v1/messages',
        headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 400,
          system: `Extract order details for this now-confirmed order from the recent conversation below, whatever language it's written in. Product/quantity/address details are often established earlier in the conversation, not necessarily in the final confirming message — read the whole thing. Reply with ONLY this JSON:
{
  "product_name": "a short summary of what's in this order (e.g. '2x Jacket, 1x Scarf'), or null",
  "delivery_address": "the delivery address/location mentioned, or null",
  "city": "just the city/area name if identifiable, or null",
  "quantity": "total item count across everything ordered, or null if not mentioned",
  "order_total": "a plain number (no currency symbols/commas), or null if not mentioned",
  "items": [ { "product_name": "...", "quantity": number, "unit_price": number or null } ]
}
For "items": list EACH distinct product separately with its own quantity, even if the order has just one product. If a per-item price isn't clearly stated, leave unit_price null.`,
          messages: [{ role: 'user', content: recentConvoText }]
        })
      });
      const extractTextBlock = ((extractResp.content || []).find(b => b && b.type === 'text') || {}).text || '{}';
      const extracted = JSON.parse(extractTextBlock.trim().replace(/```json|```/g, ''));
      if (extracted.product_name) productName = extracted.product_name;
      if (extracted.delivery_address) deliveryAddress = extracted.delivery_address;
      if (extracted.city) city = extracted.city;
      if (extracted.quantity) quantity = parseInt(extracted.quantity) || 1;
      if (Array.isArray(extracted.items)) extractedItems = extracted.items;
      if (extracted.order_total) orderTotal = parseFloat(extracted.order_total) || 0;
    } catch (e) {}

    const isWholesaleOrder = quantity >= minimumOrderQty;

    // ═══ SAVE TO ORDERS TABLE ═══
    try {
      const orderCreateResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=representation' },
        body: JSON.stringify({
          phone: phone,
          seller_id: chatId,
          product_name: productName,
          order_total: orderTotal,
          delivery_address: deliveryAddress,
          order_status: 'PENDING',
          created_at: new Date().toISOString()
        })
      });
      const createdOrderId = (orderCreateResp && orderCreateResp[0] && orderCreateResp[0].id) || null;

      if (createdOrderId && extractedItems.length > 0) {
        for (const item of extractedItems) {
          try {
            await this.helpers.httpRequest({
              method: 'POST',
              url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/order_items',
              headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
              body: JSON.stringify({
                order_id: createdOrderId,
                seller_id: chatId,
                product_name: item.product_name || '',
                quantity: item.quantity || 1,
                unit_price: item.unit_price || null,
                line_total: item.unit_price ? item.unit_price * (item.quantity || 1) : null
              })
            });
          } catch (e) {}
        }
      }
      debugResult.orderTableSaved = true;
    } catch(e) {
      debugResult.orderTableError = e.message;
    }

    // ═══════════════════════════════════════════════
    // META CAPI — "Purchase" event for Click-to-WhatsApp ad attribution.
    // Skips silently if this seller doesn't have ads tracking enabled, or
    // if this customer never came in through a tracked ad click.
    // ═══════════════════════════════════════════════
    try {
      const adConfigResp = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_ad_config?chat_id=eq.' + chatId + '&select=meta_dataset_id,meta_ads_token,waba_id,enabled&limit=1',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      const adConfig = adConfigResp && adConfigResp.length > 0 ? adConfigResp[0] : null;

      if (adConfig && adConfig.enabled === true && adConfig.meta_dataset_id && adConfig.meta_ads_token) {
        const custAdResp = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/customers?phone=eq.' + phone + '&seller_id=eq.' + chatId + '&select=ctwa_clid&limit=1',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
        });
        const ctwaClid = custAdResp && custAdResp.length > 0 ? custAdResp[0].ctwa_clid : null;

        if (ctwaClid) {
          const crypto = require('crypto');
          const hashedPhone = crypto.createHash('sha256').update(phone.trim().toLowerCase()).digest('hex');

          await this.helpers.httpRequest({
            method: 'POST',
            url: 'https://graph.facebook.com/v19.0/' + adConfig.meta_dataset_id + '/events',
            headers: { 'Authorization': 'Bearer ' + adConfig.meta_ads_token, 'Content-Type': 'application/json' },
            body: JSON.stringify({
              data: [{
                event_name: 'Purchase',
                event_time: Math.floor(Date.now() / 1000),
                action_source: 'business_messaging',
                messaging_channel: 'whatsapp',
                user_data: {
                  whatsapp_business_account_id: adConfig.waba_id,
                  ctwa_clid: ctwaClid,
                  ph: hashedPhone
                },
                custom_data: {
                  currency: currencyLabel || 'USD',
                  value: orderTotal
                }
              }]
            })
          });
          debugResult.metaCapiPurchaseSent = true;
        }
      }
    } catch(e) {
      debugResult.metaCapiError = e.message;
