// Forwards an incoming photo/video/document from the customer to the seller
// in Telegram, so they can actually see what was sent — previously these
// message types were silently dropped as empty text, invisible to everyone.
async function forwardMediaToSeller(mediaId, kind, caption) {
  try {
    const mediaInfo = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/v19.0/' + mediaId,
      headers: { 'Authorization': 'Bearer ' + metaToken }
    });
    const mediaUrl = mediaInfo && mediaInfo.url;
    if (!mediaUrl) return;

    const ext = kind === 'image' ? '.jpg' : kind === 'video' ? '.mp4' : '.pdf';
    const transferResult = await this.helpers.httpRequest({
      method: 'POST',
      url: transferServiceUrl,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        file_url: mediaUrl,
        file_name: 'customer-' + Date.now() + ext,
        auth_header: 'Bearer ' + metaToken
      })
    });
    if (!transferResult || !transferResult.success || !transferResult.url) return;

    const tgMethod = kind === 'image' ? 'sendPhoto' : kind === 'video' ? 'sendVideo' : 'sendDocument';
    const tgField = kind === 'image' ? 'photo' : kind === 'video' ? 'video' : 'document';
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/' + tgMethod,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: sellerChatId,
        [tgField]: transferResult.url,
        caption: caption
      })
    });
  } catch (e) {}
}

