} catch(e) {}

const ADMIN_ALERT_CHAT_ID = '6150148292'; // fixed admin notification channel — NOT a data fallback
const botToken = '[REDACTED_TELEGRAM_BOT_TOKEN]';

// Writes to the same system_errors table the web app's Error Log reads from
// — so a failure here shows up right alongside frontend failures, one place
// to check regardless of where something actually broke.
async function logSystemError(sellerId, source, message, context) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/system_errors',
      headers: { apikey: anonKey, Authorization: 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: JSON.stringify({ seller_id: sellerId || null, source: 'n8n:' + source, error_message: String(message).slice(0, 500), context: context || null })
    });
  } catch (e) {}
}

let metaToken = null;
let sellerChatId = null;
let phoneNumberId = incomingPhoneNumberId || null;
try {
  if (incomingPhoneNumberId) {
    const sellerLookup = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?phone_number_id=eq.' + incomingPhoneNumberId + '&select=meta_token,phone_number_id,chat_id&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    if (sellerLookup && sellerLookup.length > 0) {
      metaToken = sellerLookup[0].meta_token;
      phoneNumberId = sellerLookup[0].phone_number_id;
      sellerChatId = sellerLookup[0].chat_id;
    }
  }
} catch(e) {}

// Full halt if the seller/token can't be resolved — sending with the wrong
// credentials would deliver this reply from a DIFFERENT seller's WhatsApp
// Business account to a customer who never contacted them.
if (!metaToken) {
  await logSystemError.call(this, sellerChatId, 'send whatsapp', 'Could not resolve meta_token for phone_number_id ' + (incomingPhoneNumberId || 'unknown') + ' — message NOT sent to avoid using the wrong account', { phone, incomingPhoneNumberId });
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: ADMIN_ALERT_CHAT_ID,
        text: '🚨 ADMIN ALERT (send whatsapp): Could not resolve a valid meta_token for this seller. The message was NOT sent, to avoid sending from the wrong WhatsApp Business account.\n\nIncoming phone_number_id: ' + (incomingPhoneNumberId || 'unknown') + '\nCustomer phone: ' + phone
      })
    });
  } catch (e) {}
  return [];
}

let incomingMessageId = null;
try {
  incomingMessageId = $('webhook').first().json.body.entry[0].changes[0].value.messages[0].id;
} catch(e) { incomingMessageId = null; }

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function calculateTypingDelay(text) {
  const wordCount = (text || '').split(/\s+/).filter(Boolean).length;
  const delayMs = Math.min(Math.max(wordCount * 300, 1500), 8000);
  return delayMs;
}

// Lets the seller's dashboard show a live "Ahmad is typing..." bubble at the
// same real moment WhatsApp shows it to the customer — not a fake animation.
async function markTypingUntil(durationMs) {
  if (!sellerChatId || !phone) return;
  try {
    const until = new Date(Date.now() + durationMs).toISOString();
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/client_status?on_conflict=phone_number,seller_id',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates,return=minimal' },
      body: JSON.stringify({ phone_number: phone, seller_id: sellerChatId, ai_typing_until: until })
    });
  } catch (e) {}
}

// Step 1: mark the message as read only (blue double check appears)
async function markAsRead() {
  if (!incomingMessageId) return;
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages',
      headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        messaging_product: 'whatsapp',
        status: 'read',
        message_id: incomingMessageId
      })
    });
  } catch(e) {}
}

// Step 2: show typing indicator only (separate call, shown after the pause)
async function showTyping() {
  if (!incomingMessageId) return;
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages',
      headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        messaging_product: 'whatsapp',
        status: 'read',
        message_id: incomingMessageId,
        typing_indicator: { type: 'text' }
      })
    });
  } catch(e) {}
}

if (isNonCustomer) {
  return [{ json: { success: true, skipped: true, reason: 'non_customer' } }];
}

if (globallyPaused && phone) {
  await markAsRead.call(this);
  await sleep(2000);
  await showTyping.call(this);
  const pauseDelay = calculateTypingDelay(pauseMessage);
  await markTypingUntil.call(this, pauseDelay);
  await sleep(pauseDelay);
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages',
      headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        messaging_product: 'whatsapp',
        to: phone,
        type: 'text',
        text: { body: pauseMessage }
      })
    });
    return [{ json: { success: true, skipped: true, reason: 'globally_paused' } }];
  } catch(e) {
    await logSystemError.call(this, sellerChatId, 'send whatsapp (paused message)', e.message, { phone });
    return [{ json: { success: false, error: e.message, reason: 'globally_paused_send_failed' } }];
  }
}

if (!waBody) {
  return [{ json: { success: false, reason: 'no_waBody' } }];
}

let replyText = '';
try {
  replyText = JSON.parse(waBody).text.body;
} catch(e) {}

// 10-second pause before the blue check even appears — makes the response
// feel less instant/bot-like
await sleep(10000);
// blue check appears first
await markAsRead.call(this);
// wait 2 seconds before typing indicator shows
await sleep(2000);
// typing indicator appears
await showTyping.call(this);
// wait proportional to reply length before actually sending — already scales
// with how long the AI's actual response is, via calculateTypingDelay()
const typingDelay = calculateTypingDelay(replyText);
await markTypingUntil.call(this, typingDelay);
await sleep(typingDelay);

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages',
    headers: {
      'Authorization': 'Bearer ' + metaToken,
      'Content-Type': 'application/json'
    },
    body: waBody
  });

  return [{ json: { success: true, response } }];
} catch(e) {
  await logSystemError.call(this, sellerChatId, 'send whatsapp', 'Failed to deliver reply to customer: ' + e.message, { phone, replyText: (replyText || '').slice(0, 200) });
  return [{ json: { success: false, error: e.message } }];
}

const data = $input.first().json;
const phone = data.phone || '';
const message = data.message || '';
const history = data.history || [];

const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';
const anthropicKey = '[REDACTED_ANTHROPIC_KEY]';

// Get the customer's most recent message (what we actually detect language from)
const lastUserMsg = [...history].reverse().find(m => m.role === 'user');
const msgToCheck = message || (lastUserMsg ? lastUserMsg.content : '');

let detectedLanguageName = 'English';
let detectedDialect = '';

// Only bother calling AI if there's actually text to check
if (msgToCheck && msgToCheck.trim().length > 0) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: {
        'x-api-key': anthropicKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 40,
        system: `You are a language identification engine. You will be given one short message. Identify:
1. The language it is written in (could be any of 100+ world languages)
2. The specific dialect, regional accent, or speaking style if identifiable (e.g. "Iraqi" for Arabic, "Sorani" for Kurdish, "Istanbul casual" for Turkish, "American" for English, etc). If not identifiable, leave dialect blank.

Respond with ONLY this exact format, nothing else, no explanation:
LANGUAGE: <language name>
DIALECT: <dialect name or blank>`,
        messages: [{ role: 'user', content: msgToCheck }]
      })
    });

    const text = response && response.content && response.content[0] && response.content[0].text || '';
    const langMatch = text.match(/LANGUAGE:\s*(.+)/i);
    const dialectMatch = text.match(/DIALECT:\s*(.*)/i);
    if (langMatch && langMatch[1].trim()) detectedLanguageName = langMatch[1].trim();
    if (dialectMatch && dialectMatch[1].trim()) detectedDialect = dialectMatch[1].trim();
  } catch (e) {
    // If detection fails, fall back to the customer's previously saved language if we have one
    detectedLanguageName = 'English';
    detectedDialect = '';
  }
}

// Save detected language/dialect to the customer record (fire and forget, doesn't block the reply)
if (phone) {
  try {
    const cleanPhone = phone.replace(/=/g, '').replace(/\+/g, '');
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/customers?phone=eq.' + cleanPhone,
      headers: {
        'apikey': anonKey,
        'Authorization': 'Bearer ' + anonKey,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ preferred_language: detectedLanguageName, preferred_dialect: detectedDialect })
    });
  } catch (e) {}
}

// Pass everything forward unchanged, plus the two new detected fields
return [{ json: { ...data, detectedLanguageName, detectedDialect } }];

let ctwa_clid = null;
let ad_id = null;
let ad_headline = null;

try {
  const message = $input.first().json.body.entry[0].changes[0].value.messages[0];
  const referral = message.referral || null;
  ctwa_clid = referral?.ctwa_clid || null;
  ad_id = referral?.source_id || null;
  ad_headline = referral?.headline || null;
} catch (e) {
  // Normal, expected case for any message that didn't come from a
  // Click-to-WhatsApp ad — there's simply no referral data to extract.
  // Never let this break the rest of the pipeline.
}

return {
  ...$input.first().json,
  ctwa_clid,
  ad_id,
  ad_headline,
};

let adContext = '';
let sellerChatId = null;
let adId = null;

try {
  adId = $json.ad_id || null;
  const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';

  // ═══ RESOLVE WHICH SELLER OWNS THIS CONVERSATION ═══
  // seller_chat_id was previously a placeholder that nothing upstream populated.
  // Resolved here the same way every other node in this pipeline does it — via
  // the webhook's phone_number_id — rather than introducing a separate centralized
  // "Resolve Seller" node.
  try {
    const incomingPhoneNumberId = $('webhook').first().json.body.entry[0].changes[0].value.metadata.phone_number_id;
    if (incomingPhoneNumberId) {
      const sellerLookup = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?phone_number_id=eq.' + incomingPhoneNumberId + '&select=chat_id&limit=1',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      if (sellerLookup && sellerLookup.length > 0) sellerChatId = sellerLookup[0].chat_id;
    }
  } catch (e) {}

  if (adId && sellerChatId) {
    const rows = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/ad_product_mapping?chat_id=eq.' + sellerChatId + '&ad_id=eq.' + adId + '&select=product_name,offer_details',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    const match = Array.isArray(rows) && rows.length > 0 ? rows[0] : null;

    if (match) {
      adContext = `This customer clicked an ad for "${match.product_name}"${match.offer_details ? ` with this offer: ${match.offer_details}` : ''}. Lead with this product and offer unless they ask about something else.`;
    }
  }
} catch (e) {
  // Never let this break the rest of the pipeline — ad context is a
  // nice-to-have enrichment, not something the sale depends on.
  adContext = '';
}

return { ...$json, ad_context: adContext };
